head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil11000";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil11000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_disclsTitle", fn: function () { return String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "cal_startDate", fn: function () { return String(String((dma_pageContext.get("startDate") ?? ""))); } },
        { childId: "cal_endDate", fn: function () { return String(String((dma_pageContext.get("endDate") ?? ""))); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_page.get("total")) + "건 (" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("endListPage")) + " 페이지) "; } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#ipt_disclsTitle').keydown(async function(key) {
                if (key.keyCode === 13) {
                    await scwin.searchList();
                }
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil11000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cal_startDate_onblur
 * @description cal_startDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_startDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_startDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11000.cal_startDate_onblur' }); }
};

/**
 * @method
 * @name cal_endDate_onblur
 * @description cal_endDate 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal_endDate_onblur = async function(e){
    try {
        await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = ""; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent("cal_endDate"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11000.cal_endDate_onblur' }); }
};

/**
 * @method
 * @name btn_searchList_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchList_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11000.btn_searchList_onclick' }); }
};

/**
 * @method
 * @name btn_goWrite_onclick
 * @description 「작성하기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goWrite_onclick = async function(e){
    try {
        await scwin.goWrite()
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil11000.btn_goWrite_onclick" });
    }
};

/**
 * @method
 * @name __ev_5_btn_goWrite_onclick
 * @description __ev_5_btn_goWrite 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__ev_5_btn_goWrite_onclick = async function(e){
    try {
        await scwin.goWrite()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11000.__ev_5_btn_goWrite_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil11000.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description grd_list 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_list_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_list');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_list */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        await scwin.goView(r["disclsConsultApplId"], r["disclsConsultProcsStatCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_list.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_83_onclick
 * @description krxpage_pagenavigator_83 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_83_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_searchListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_83.page' }); } await scwin.tx_fn_searchList(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_searchListReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil11000.tx_fn_searchList" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] !== null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_83").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_goWriteReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goView
 * @description go View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goView = async function () {
    const sbmOptions = {
        id: "tx_fn_goView",
        method: "post",
        action: "/status/disclsConsult.do",
        ref: "dma_goViewReq",
        target: "dlt_list=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('ipt_method').setValue("disclsConsultApplList");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do") */
    $("form[name='disclsConsultForm']").attr("onsubmit", "");
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function () {
    $c.util.getComponent('ipt_method').setValue("disclsConsultAppl");
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do") */
    const nr = await scwin.tx_fn_goWrite();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil11010/jldfil11010.xml", { "method": "disclsConsultAppl" });
    }
};

/**
 * @method
 * @name goView
 * @description go View 처리
 * @param {String} ipt_disclsConsultApplId ipt_disclsConsultApplId
 * @param {String} disclsConsultProcsStatCd disclsConsultProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goView = async function (ipt_disclsConsultApplId, disclsConsultProcsStatCd) {
    if (disclsConsultProcsStatCd === '1') {
        $c.util.getComponent('ipt_method').setValue("disclsConsultAppl");
    } else {
        $c.util.getComponent('ipt_method').setValue("disclsConsultApplView");
    }
    $c.util.getComponent('ipt_disclsConsultApplId').setValue(ipt_disclsConsultApplId);
    /* TODO Stage2(규칙19): 폼 action 지정은 tx 로 대체되어 사문 — $("form[name='disclsConsultForm']").attr("action", "disclsConsult.do") */
    const nr = await scwin.tx_fn_goView();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil11010/jldfil11010.xml", { "method": "disclsConsultAppl", "disclsConsultApplId": ipt_disclsConsultApplId });
    }
};
